using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Tilemaps;
using Object = UnityEngine.Object;

namespace Komur.EditorTools
{
    // Paints the town from Assets/_Game/Map/town-map.json (generated by tools/mapgen/build_town_map.py).
    // docs/ui-design/map-spec.html renders the same file with the same tile rules, so the design page and
    // the scene match. Coordinates are tile cells, (0,0) bottom-left, y up.
    public static partial class KomurSceneBuilder
    {
        private const string TownScenePath = GameRoot + "/Scenes/Town.unity";
        private const string TownMapPath = GameRoot + "/Map/town-map.json";

        [Serializable]
        private class TownMap
        {
            [Serializable] public class Stair { public int x; public int capY; }
            [Serializable] public class Marker { public float x; public float y; public int f = 1; public int wave = 1; }
            [Serializable] public class Prop { public string p; public float x; public float y; public int f = 1; }

            public int width, height;
            public string[] rows;
            public Stair[] stairs;
            public float[] komur, apothecary;
            public Marker[] villagers, holes;
            public Prop[] props;

            // rows are stored top to bottom
            public char At(int x, int y) => x < 0 || y < 0 || x >= width || y >= height ? ' ' : rows[height - 1 - y][x];
            public bool Room(int x, int y) => At(x, y) != ' ';
            public bool Raised(int x, int y) { char c = At(x, y); return c == '^' || c == 'B'; }
            public bool Pit(int x, int y) { char c = At(x, y); return c == 's' || c == 'r'; }
            public bool Ramp(int x, int y) => At(x, y) == 'r';
            public bool SolidPit(int x, int y) => At(x, y) == 's';
        }

        [MenuItem("Kömür/Build Town Scene (town-map.json)", priority = 3)]
        public static void BuildTownScene()
        {
            if (!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()) return;
            var json = AssetDatabase.LoadAssetAtPath<TextAsset>(TownMapPath);
            if (json == null)
            {
                EditorUtility.DisplayDialog("Kömür", "Missing " + TownMapPath + ". Run tools/mapgen/build_town_map.py first.", "OK");
                return;
            }
            var map = JsonUtility.FromJson<TownMap>(json.text);
            if (File.Exists(TownScenePath) &&
                !EditorUtility.DisplayDialog("Kömür", "Town.unity already exists. Rebuild it from scratch?", "Rebuild", "Cancel"))
                return;

            var prefabs = BuildPrefabsAndSettings();

            // Start from the demo scene so tilemaps, sorting layers, colliders and camera are configured.
            if (File.Exists(TownScenePath)) AssetDatabase.DeleteAsset(TownScenePath);
            AssetDatabase.CopyAsset(CainosRoot + "/Scene/SC Demo.unity", TownScenePath);
            var scene = EditorSceneManager.OpenScene(TownScenePath);
            var maps = StripDemoScene(scene);
            Tilemap Get(string name) => maps.TryGetValue(name, out var tm) ? tm : null;
            var grass1 = Get("Layer 1 - Grass");
            var stone1 = Get("Layer 1 - Stone Ground") ?? grass1;
            var wall1 = Get("Layer 1 - Wall");
            var shadow1 = Get("Layer 1 - Wall Shadow");
            var grass2 = Get("Layer 2 - Grass");
            var wall2 = Get("Layer 2 - Wall");
            if (grass1 == null || wall1 == null || grass2 == null || wall2 == null)
            {
                Debug.LogError("[Kömür] Demo tilemaps not found; cannot paint the town.");
                return;
            }

            PaintTown(map, grass1, stone1, wall1, shadow1, grass2, wall2);
            foreach (var tm in maps.Values) tm.CompressBounds();
            Physics2D.SyncTransforms();

            Vector3 origin = grass1.CellToWorld(Vector3Int.zero);
            Vector3 W(float x, float y) => origin + new Vector3(x, y, 0f);

            var propsRoot = new GameObject("Props").transform;
            var stairsPrefab = AssetDatabase.LoadAssetAtPath<GameObject>($"{CainosRoot}/Prefab/Props/PF Struct - Stairs S 01 M.prefab");
            foreach (var s in map.stairs)
            {
                var go = (GameObject)PrefabUtility.InstantiatePrefab(stairsPrefab, propsRoot);
                go.transform.position = W(s.x, s.capY + 1);
            }
            foreach (var p in map.props) PlaceMapProp(p.p, W(p.x, p.y), propsRoot, p.f);

            BuildApothecary(W(map.apothecary[0], map.apothecary[1]));
            SetupScene(prefabs, W(map.komur[0], map.komur[1]));
            foreach (var v in map.villagers) PlaceVillager(prefabs.villager, W(v.x, v.y), v.f);
            foreach (var h in map.holes) PlaceRatHole(prefabs.ratHole, W(h.x, h.y), h.f, h.wave);

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            AddSceneToBuildSettings(TownScenePath);
            Debug.Log($"[Kömür] Town built from {TownMapPath}: {map.props.Length} props. Turn on NavGrid gizmos to check walkable areas.");
        }

        // ---------- Painting (keep in sync with docs/ui-design/map-spec.html) ----------

        private static uint TileHash(int x, int y) => unchecked((uint)(x * 73856093) ^ (uint)(y * 19349663));

        private static void PaintTown(TownMap m, Tilemap grass1, Tilemap stone1, Tilemap wall1, Tilemap shadow1, Tilemap grass2, Tilemap wall2)
        {
            var gaps = new HashSet<Vector2Int>();
            foreach (var s in m.stairs) { gaps.Add(new Vector2Int(s.x - 1, s.capY)); gaps.Add(new Vector2Int(s.x, s.capY)); }

            for (int y = 0; y < m.height; y++)
            for (int x = 0; x < m.width; x++)
            {
                var cell = new Vector3Int(x, y, 0);
                char c = m.At(x, y);
                uint h = TileHash(x, y);
                if (c == ' ') continue; // outside the town

                // Ground floor: grass everywhere, cobbles on paths, 9-sliced stone on plazas.
                if (c == '=') grass1.SetTile(cell, LoadTile("TP Grass", "TX Tileset Grass Pavement " + h % 8));
                else if (c == ',') grass1.SetTile(cell, LoadTile("TP Grass", "TX Tileset Grass Flower " + h % 16));
                else grass1.SetTile(cell, LoadTile("TP Grass", "TX Tileset Grass " + h % 16));
                if (c == '#') stone1.SetTile(cell, Stone(StoneIndex(m, x, y)));

                // Upper floor grass on raised ground.
                if (m.Raised(x, y))
                    grass2.SetTile(cell, LoadTile("TP Grass", h % 7 == 0 ? "TX Tileset Grass Flower " + h % 16 : "TX Tileset Grass " + h % 16));

                int room = RoomTile(m, x, y);
                int w1 = room >= 0 ? room : Wall1Tile(m, x, y);
                if (w1 >= 0) wall1.SetTile(cell, Wall(w1));
                int w2 = m.Raised(x, y) ? RaisedTile(m, x, y) : -1;
                if (w2 >= 15 && w2 <= 17 && gaps.Contains(new Vector2Int(x, y))) w2 = -1;
                if (w2 >= 0) wall2.SetTile(cell, Wall(w2));

                if (shadow1 != null)
                {
                    int sh = ShadowTile(m, x, y);
                    if (sh > 0) shadow1.SetTile(cell, LoadTile("TP Wall", "TX Shadow Tileset Wall " + sh));
                }
            }

        }

        // Town wall following the outline: rim on top, rims on the sides, cap + brick face along the bottom.
        private static int RoomTile(TownMap m, int x, int y)
        {
            if (!m.Room(x, y)) return -1;
            bool w = m.Room(x - 1, y), e = m.Room(x + 1, y);
            if (!m.Room(x, y + 1)) return !w ? 0 : !e ? 2 : 1;
            if (!m.Room(x, y - 1)) return !w ? 23 : !e ? 25 : 24;
            if (!m.Room(x, y - 2)) return !w ? 15 : !e ? 17 : 16;
            if (!w) return 8;
            if (!e) return 9;
            if (!m.Room(x - 1, y + 1)) return 22;
            if (!m.Room(x + 1, y + 1)) return 18;
            return -1;
        }

        private static int StoneIndex(TownMap m, int x, int y)
        {
            bool n = m.At(x, y + 1) == '#', s = m.At(x, y - 1) == '#', w = m.At(x - 1, y) == '#', e = m.At(x + 1, y) == '#';
            int col = !w ? 0 : !e ? 2 : 1;
            int row = !n ? 0 : !s ? 2 : 1;
            return row * 8 + col;
        }

        // Outline of raised ground: rims on top/sides, cap along the bottom, inner corners where the outline turns.
        private static int RaisedTile(TownMap m, int x, int y)
        {
            bool n = m.Raised(x, y + 1), s = m.Raised(x, y - 1), w = m.Raised(x - 1, y), e = m.Raised(x + 1, y);
            if (!n) return !w ? 0 : !e ? 2 : 1;
            if (!s) return !w ? 15 : !e ? 17 : 16;
            if (!w) return 8;
            if (!e) return 9;
            if (!m.Raised(x - 1, y + 1)) return 22;
            if (!m.Raised(x + 1, y + 1)) return 18;
            return -1;
        }

        // Ground-floor walls: raised outlines + their brick faces, and the sunken graveyard's walls.
        private static int Wall1Tile(TownMap m, int x, int y)
        {
            if (m.Raised(x, y)) return RaisedTile(m, x, y);

            // Brick face under the bottom edge of raised ground.
            if (m.Raised(x, y + 1))
                return !m.Raised(x - 1, y + 1) ? 23 : !m.Raised(x + 1, y + 1) ? 25 : 24;

            if (m.Pit(x, y))
            {
                // The pit's north wall: the higher ground's brick face, seen from inside.
                if (m.SolidPit(x, y) && !m.Pit(x, y + 1))
                    return !m.Pit(x - 1, y) ? 23 : !m.Pit(x + 1, y) ? 25 : 24;
                return -1;
            }

            // Ground around the pit: cap above its north wall, rims on the other sides, inner corners.
            if (m.SolidPit(x, y - 1) && !m.Pit(x, y))
                return !m.Pit(x - 1, y - 1) ? 15 : !m.Pit(x + 1, y - 1) ? 17 : 16;
            if (m.SolidPit(x, y + 1)) return 1;
            if (m.SolidPit(x + 1, y)) return 9;
            if (m.SolidPit(x - 1, y)) return 8;
            if (m.SolidPit(x + 1, y + 1) && !m.Pit(x + 1, y) && !m.Pit(x, y + 1)) return 18;
            if (m.SolidPit(x - 1, y + 1) && !m.Pit(x - 1, y) && !m.Pit(x, y + 1)) return 22;
            return -1;
        }

        // Drop shadow east of raised ground: 1 above the top corner, 2 along the side, 3 beside the brick face.
        private static int ShadowTile(TownMap m, int x, int y)
        {
            if (m.Raised(x, y)) return 0;
            if (m.Raised(x - 1, y)) return 2;
            if (m.Raised(x - 1, y + 1) && !m.Raised(x, y + 1)) return 3;
            if (m.Raised(x - 1, y - 1) && !m.Raised(x, y - 1)) return 1;
            return 0;
        }

        private static GameObject PlaceMapProp(string relativePath, Vector3 position, Transform parent, int floor)
        {
            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>($"{CainosRoot}/Prefab/{relativePath}.prefab");
            if (prefab == null)
            {
                Debug.LogWarning("[Kömür] Missing prefab " + relativePath);
                return null;
            }
            var go = (GameObject)PrefabUtility.InstantiatePrefab(prefab, parent);
            go.transform.position = position;
            if (floor != 1) MoveToFloor(go, floor);
            return go;
        }

        private static void MoveToFloor(GameObject go, int floor)
        {
            string name = FloorAgent.LayerName(floor);
            int layer = LayerMask.NameToLayer(name);
            int ground = LayerMask.NameToLayer(FloorAgent.LayerName(1));
            foreach (var r in go.GetComponentsInChildren<Renderer>(true)) r.sortingLayerName = name;
            foreach (var t in go.GetComponentsInChildren<Transform>(true))
                if (layer >= 0 && (t.gameObject.layer == ground || t.gameObject.layer == 0)) t.gameObject.layer = layer;
        }

        // ---------- Scene prep ----------

        // Keeps camera, lights and the tilemap grid (cleared); removes demo props, plants, stairs and the player.
        private static Dictionary<string, Tilemap> StripDemoScene(UnityEngine.SceneManagement.Scene scene)
        {
            var keepers = new List<Transform>();
            foreach (var root in scene.GetRootGameObjects())
            {
                foreach (var cam in root.GetComponentsInChildren<Camera>(true)) keepers.Add(cam.transform);
                foreach (var grid in root.GetComponentsInChildren<Grid>(true)) keepers.Add(grid.transform);
                foreach (var c in root.GetComponentsInChildren<Component>(true))
                    if (c != null && c.GetType().Name.Contains("Light2D")) keepers.Add(c.transform);
            }
            foreach (var k in keepers.Distinct()) k.SetParent(null, true);
            foreach (var root in scene.GetRootGameObjects())
                if (!keepers.Contains(root.transform)) Object.DestroyImmediate(root);

            var maps = new Dictionary<string, Tilemap>();
            foreach (var grid in Object.FindObjectsByType<Grid>(FindObjectsSortMode.None))
            {
                foreach (Transform child in grid.transform.Cast<Transform>().ToArray())
                    if (child.GetComponent<Tilemap>() == null) Object.DestroyImmediate(child.gameObject);
                foreach (var tm in grid.GetComponentsInChildren<Tilemap>(true))
                {
                    tm.ClearAllTiles();
                    maps[tm.gameObject.name] = tm;
                }
            }
            foreach (var k in keepers.Where(k => k != null && k.GetComponent<Grid>() == null))
                foreach (Transform child in k.Cast<Transform>().ToArray())
                    Object.DestroyImmediate(child.gameObject);

            EnsureCamera();
            return maps;
        }

        private static void EnsureCamera()
        {
            if (Camera.main != null) return;
            var go = new GameObject("Main Camera") { tag = "MainCamera" };
            var cam = go.AddComponent<Camera>();
            cam.orthographic = true;
            cam.orthographicSize = 5f;
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.1f, 0.1f, 0.12f);
            go.transform.position = new Vector3(0f, 0f, -10f);
        }

        // ---------- Tiles ----------

        private static readonly Dictionary<string, TileBase> tileCache = new Dictionary<string, TileBase>();

        private static TileBase LoadTile(string palette, string name)
        {
            string key = palette + "/" + name;
            if (tileCache.TryGetValue(key, out var cached) && cached != null) return cached;
            var tile = AssetDatabase.LoadAssetAtPath<TileBase>($"{CainosRoot}/Tile Palette/{palette}/{name}.asset");
            if (tile == null) Debug.LogWarning("[Kömür] Missing tile " + name);
            tileCache[key] = tile;
            return tile;
        }

        private static TileBase Wall(int n) => LoadTile("TP Wall", "TX Tileset Wall_" + n);
        private static TileBase Stone(int n) => LoadTile("TP Stone Ground", "TX Tileset Stone Ground_" + n);

        // Cainos "room" outline: rim on top and sides, cap row, then a brick face row underneath.
        // r.y is the face row; r.yMax - 1 is the top rim.
        private static void PaintRoom(Tilemap tm, RectInt r, bool withFace)
        {
            int left = r.xMin, right = r.xMax - 1, face = r.yMin, cap = r.yMin + 1, top = r.yMax - 1;
            for (int x = left; x <= right; x++)
            {
                tm.SetTile(new Vector3Int(x, top, 0), Wall(x == left ? 0 : x == right ? 2 : 1));
                tm.SetTile(new Vector3Int(x, cap, 0), Wall(x == left ? 15 : x == right ? 17 : 16));
                if (withFace) tm.SetTile(new Vector3Int(x, face, 0), Wall(x == left ? 23 : x == right ? 25 : 24));
            }
            for (int y = cap + 1; y < top; y++)
            {
                tm.SetTile(new Vector3Int(left, y, 0), Wall(8));
                tm.SetTile(new Vector3Int(right, y, 0), Wall(9));
            }
        }
    }
}
